// Build CBSE 12 Mathematics ch04 Determinants. Run from platform/:
//   npx tsx content/authored/maths/cbse-12-mathematics-ch04/src/build.mjs
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { setUnit, topic, deck, sl, plot, table, flow, build, chapterTests, r } from '../../cbse-12-mathematics-ch01/src/lib.mjs';
import { mul, scal, I, eqM, isInverse, col, det, minor, cof, cofM, adj, expandRow, expandCol, triDet, area, solve, classify, bm, vm } from './det.mjs';

setUnit('cbse-12-mathematics-ch04');
await import('./questions.mjs');
const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

// ---------------------------------------------------------------- self-checks for every worked example on slides and in notes
const fail = [];
const must = (cond, msg) => { if (!cond) fail.push(msg); };
const eqv = (u, v) => u.length === v.length && u.every((x, i) => Math.abs(x - v[i]) < 1e-9);
const W1 = [[5, -3], [4, 2]];
must(det(W1) === 22, 'deck1 WE1');
const W2 = [[2, -1, 3], [1, 4, 0], [-2, 1, 5]];
must(det(W2) === 72 && expandRow(W2, 1) === 72 && expandCol(W2, 3) === 72 && cof(W2, 1, 3) === 9 && cof(W2, 3, 3) === 9, 'deck1 WE2 both expansions');
must(minor(W2, 1, 1) === 20 && minor(W2, 1, 2) === 5 && minor(W2, 1, 3) === 9, 'deck1 WE2 minors');
const w3 = (x) => det([[x, 4], [x, 2 * x]]) - det([[3, -2], [5, 2]]);
must([4, -2].every((x) => w3(x) === 0) && det([[3, -2], [5, 2]]) === 16, 'deck1 WE3 roots 4, -2');
const T1 = [[1, 2], [5, 4], [3, 7]];
must(triDet(...T1) === 16 && area(...T1) === 8, 'deck1 WE4 area 8');
must(triDet([0, 0], [4, 0], [0, 2]) === 8 && triDet([8, 0], [4, 0], [0, 2]) === -8 && area([0, 0], [4, 0], [0, 2]) === 4 && area([8, 0], [4, 0], [0, 2]) === 4, 'deck1 WE5 k = 0 or 8');
must([0, 1, 2, 3, 4, 6, 7].every((k) => Math.abs(triDet([k, 0], [4, 0], [0, 2]) - (8 - 2 * k)) < 1e-9), 'deck1 WE5 det = 8 - 2k');
must(triDet([1, -1], [3, 3], [5, 7]) === 0 && [0, 1, 2, 3, 4, 6].every((k) => triDet([1, -1], [3, 3], [k, 7]) === 20 - 4 * k), 'deck1 WE6 collinear k = 5');
must([[0, 0], [1, 0], [0, 1]].every(([x, y]) => triDet([x, y], [2, 1], [4, 5]) === -4 * x + 2 * y + 6), 'deck1 WE7 line -4x + 2y + 6');
const Qm = [[2, 1, 3], [1, -1, 0], [0, 2, 1]];
must(det(Qm) === 3 && eqM(cofM(Qm), [[-1, -1, 2], [5, 2, -4], [3, 3, -3]]) && eqM(adj(Qm), [[-1, 5, 3], [-1, 2, 3], [2, -4, -3]]), 'deck2 Q cofactors and adjoint');
must(eqM(mul(Qm, adj(Qm)), scal(3, I(3))) && isInverse(Qm, scal(1 / 3, adj(Qm))), 'deck2 Q inverse');
const S2 = [[6, 2], [5, 3]];
must(det(S2) === 8 && eqM(adj(S2), [[3, -2], [-5, 6]]) && isInverse(S2, scal(1 / 8, [[3, -2], [-5, 6]])), 'deck2 2x2 inverse');
const E2 = [[3, 2], [5, -4]];
must(det(E2) === -22 && eqv(solve(E2, [7, 19]), [3, -1]) && eqM(adj(E2), [[-4, -2], [-5, 3]]) && eqv(mul(adj(E2), col([7, 19])).flat(), [-66, 22]), 'deck2 2-variable system');
const E3 = [[1, 1, 1], [2, -1, 1], [1, 2, -1]];
must(det(E3) === 7 && eqM(adj(E3), [[-1, 3, 2], [3, -2, 1], [5, -1, -3]]) && eqv(mul(adj(E3), col([4, 8, -3])).flat(), [14, -7, 21]) && eqv(solve(E3, [4, 8, -3]), [2, -1, 3]), 'deck2 3-variable system');
const Sg = [[1, 2], [2, 4]];
must(det(Sg) === 0 && eqv(mul(adj(Sg), col([3, 5])).flat(), [2, -1]) && eqv(mul(adj(Sg), col([3, 6])).flat(), [0, 0]) && classify(Sg, [3, 5]) === 'none' && classify(Sg, [3, 6]) === 'infinite', 'deck2 singular systems');
if (fail.length) { console.error('SLIDE SELF-CHECK FAILURES:\n  ' + fail.join('\n  ')); process.exit(1); }

// ---------------------------------------------------------------- visuals: deck 1
const triPlot = plot({ x: [0, 6], y: [0, 8], fns: [{ expr: '2 + (x - 1)/2', label: '$PQ$', domain: [1, 5] }, { expr: '4 - 1.5(x - 5)', label: '$QR$', domain: [3, 5] }, { expr: '2 + 2.5(x - 1)', label: '$PR$', domain: [1, 3] }], pts: [[1, 2, 'P(1, 2)'], [5, 4, 'Q(5, 4)'], [3, 7, 'R(3, 7)']] }, 'A triangle drawn on a grid with vertices P at 1 comma 2, Q at 5 comma 4 and R at 3 comma 7. Its area can be found from the coordinates of the vertices alone.', 'Triangle $PQR$: area $= \\frac12|16| = 8$ square units.');
