const we2bTbl = table(['Element of column 3', 'Cofactor', 'Product'], [['$a_{13} = 3$', r`$+\begin{vmatrix} 1 & 4 \\ -2 & 1 \end{vmatrix} = 9$`, '$27$'], ['$a_{23} = 0$', 'not needed', '$0$'], ['$a_{33} = 5$', r`$+\begin{vmatrix} 2 & -1 \\ 1 & 4 \end{vmatrix} = 9$`, '$45$'], ['', 'Total', '$72$']], 'Table expanding the same determinant along column 3: element 3 with cofactor 9 gives 27; element 0 needs no cofactor; element 5 with cofactor 9 gives 45; the total is again 72.', 'Same determinant, different column, same value — with less work.');
const zeroFlow = flow('TB', [['s', 'Look at every row and column'], ['q', 'Which line has the most zeros?'], ['e', 'Expand along it: zero entries need no minor'], ['t', 'Tie? Choose the line with the smallest numbers'], ['c', 'Optional check: expand along a second line']], [['s', 'q'], ['q', 'e', 'clear winner'], ['q', 't', 'tie'], ['t', 'e'], ['e', 'c']], 'Decision chart for choosing where to expand: look at every row and column, pick the one with the most zeros because zero entries need no minor; if there is a tie, pick the line with the smallest numbers; optionally check by expanding along a second line.', 'Zeros save work; the value never depends on the choice.');
const we3Plot = plot({ x: [-4, 6], y: [-10, 8], fns: [{ expr: 'x^2 - 2x - 8', label: '$y = x^2 - 2x - 8$' }], pts: [[-2, 0, '(−2, 0)'], [4, 0, '(4, 0)']] }, 'Graph of the parabola y equals x squared minus 2 x minus 8, crossing the x-axis at x equals minus 2 and x equals 4, the two solutions of the determinant equation.', 'The determinant equation reduces to $x^2 - 2x - 8 = 0$: roots $-2$ and $4$.');
const areaTbl = table(['Step', 'Working'], [['Set up', r`$\Delta = \begin{vmatrix} 1 & 2 & 1 \\ 5 & 4 & 1 \\ 3 & 7 & 1 \end{vmatrix}$`], ['Expand along row 1', '$1(4 - 7) - 2(5 - 3) + 1(35 - 12)$'], ['Simplify', '$-3 - 4 + 23 = 16$'], ['Area', r`$\frac12|16| = 8$ square units`]], 'Table of steps for the area of triangle P Q R: set up the determinant of the vertex coordinates with a column of ones, expand along row 1 to get minus 3 minus 4 plus 23, which is 16, and take half its absolute value, 8 square units.', 'Coordinates in rows, a column of ones, half the absolute value.');
const kPlot = plot({ x: [-1, 9], y: [-1, 3], fns: [{ expr: '2 - x/2', label: '$k = 0$ side', domain: [0, 4] }, { expr: '2 - x/4', label: '$k = 8$ side', domain: [0, 8] }], pts: [[0, 2, '(0, 2)'], [4, 0, '(4, 0)'], [8, 0, '(8, 0)'], [0, 0, '(0, 0)', 'free']] }, 'Two triangles sharing the side from 0 comma 2 to 4 comma 0. The first has its third vertex at the origin, 0 comma 0; the second has it at 8 comma 0. Both have area 4 square units.', 'Two positions of $(k, 0)$ give area $4$: $k = 0$ and $k = 8$.');
kPlot.spec.points[3].on_curve = false; // the origin is the k = 0 vertex, not a point of either drawn side
must(kPlot.spec.points[3].at[0] === 0 && kPlot.spec.points[3].at[1] === 0, 'free point is the origin');
const collPlot = plot({ x: [-1, 7], y: [-3, 9], fns: [{ expr: '2x - 3', label: '$y = 2x - 3$' }], pts: [[1, -1, '(1, −1)'], [3, 3, '(3, 3)'], [5, 7, '(5, 7)']] }, 'A straight line with three marked points: 1 comma minus 1, 3 comma 3 and 5 comma 7. All three lie on the same line, so the triangle they form is flat and has zero area.', 'With $k = 5$, the point $(5, 7)$ joins the line: zero area, collinear.');
const linePlot = plot({ x: [-1, 6], y: [-4, 8], fns: [{ expr: '2x - 3', label: '$2x - y - 3 = 0$' }], pts: [[2, 1, '(2, 1)'], [4, 5, '(4, 5)']] }, 'The line through 2 comma 1 and 4 comma 5, which is y equals 2 x minus 3. Any point on it makes the determinant with these two points equal to zero.', 'A general point $(x, y)$ collinear with two fixed points traces the line.');
const sum1Flow = flow('LR', [['d', '$2 \\times 2$: $ad - bc$'], ['e', '$3 \\times 3$: expand along any row or column with signs $(-1)^{i + j}$'], ['a', r`Area $= \frac12|\Delta|$`], ['c', r`$\Delta = 0$: collinear; line through two points`]], [['d', 'e'], ['e', 'a'], ['a', 'c']], 'Summary chain for part one: a two by two determinant is a d minus b c; a three by three determinant is expanded along any row or column with alternating signs; the area of a triangle is half the absolute value of the vertex determinant; a zero determinant means collinear points and gives the equation of a line.', 'Part 1 at a glance.');
const tips1Tbl = table(['Task', 'Marks', 'What earns them'], [['Evaluate a $3 \\times 3$ determinant', '$1$–$2$', 'expansion with signs shown, correct value'], ['Solve a determinant equation', '$2$–$3$', 'expansion, simplified equation, all roots'], ['Area of a triangle', '$2$–$3$', 'determinant set up, value, half of absolute value with units'], ['Unknown from area', '$3$', 'both signs: $\\Delta = \\pm 2 \\times$ area'], ['Collinearity / line', '$2$', 'determinant $= 0$ stated and solved']], 'Table of exam tasks for part one with marks and what earns them: evaluating a determinant, solving a determinant equation, area of a triangle with units, finding an unknown from an area using both signs, and collinearity or the equation of a line.', 'Show the expansion; the method marks are in the steps.');

