const mcDefTbl = table(['Term', 'How to get it', 'Example in $\\begin{vmatrix} 2 & 1 & 3 \\\\ 1 & -1 & 0 \\\\ 0 & 2 & 1 \\end{vmatrix}$'], [['Minor $M_{21}$', 'delete row 2 and column 1, evaluate', r`$\begin{vmatrix} 1 & 3 \\ 2 & 1 \end{vmatrix} = -5$`], ['Cofactor $A_{21}$', r`$(-1)^{2 + 1}M_{21}$`, '$5$'], ['Minor $M_{33}$', 'delete row 3 and column 3', r`$\begin{vmatrix} 2 & 1 \\ 1 & -1 \end{vmatrix} = -3$`], ['Cofactor $A_{33}$', r`$(-1)^{6}M_{33}$`, '$-3$']], 'Table defining minors and cofactors with examples from the three by three matrix with rows 2 1 3, 1 minus 1 0 and 0 2 1: the minor in row 2, column 1 is minus 5 and its cofactor is 5; the minor in row 3, column 3 is minus 3 and its cofactor is also minus 3.', 'Minor: delete and evaluate. Cofactor: minor with the chessboard sign.');
